1	//
2	//  BPSideBarController.m
3	//  Cakebrew
4	//
5	//  Created by Marek Hrusovsky on 05/09/14.
6	//  Copyright (c) 2014 Bruno Philipe. All rights reserved.
7	//
8	
9	#import "BPSideBarController.h"
10	#import "BPHomebrewManager.h"
11	
12	@interface BPSideBarController()
13	
14	@property (strong, nonatomic) PXSourceListItem *rootSidebarCategory;
15	
16	@property (strong, nonatomic) PXSourceListItem *instaledFormulaeSidebarItem;
17	@property (strong, nonatomic) PXSourceListItem *outdatedFormulaeSidebarItem;
18	@property (strong, nonatomic) PXSourceListItem *allFormulaeSidebarItem;
19	@property (strong, nonatomic) PXSourceListItem *leavesFormulaeSidebarItem;
20	@property (strong, nonatomic) PXSourceListItem *repositoriesFormulaeSidebarItem;
21	
22	@end
23	
24	@implementation BPSideBarController
25	
26	- (instancetype)init
27	{
28		self = [super init];
29		if (self) {
30			[self buildSidebarTree];
31		}
32		return self;
33	}
34	
35	- (void)buildSidebarTree
36	{
37		PXSourceListItem *item, *parent;
38		_rootSidebarCategory = [PXSourceListItem itemWithTitle:@"" identifier:@"root"];
39		
40		parent = [PXSourceListItem itemWithTitle:NSLocalizedString(@"Sidebar_Group_Formulae", nil)
41									  identifier:@"group"];
42		[_rootSidebarCategory addChildItem:parent];
43		
44		_instaledFormulaeSidebarItem = [PXSourceListItem itemWithTitle:NSLocalizedString(@"Sidebar_Item_Installed", nil)
45															identifier:@"item"];
46		_instaledFormulaeSidebarItem.icon = [self installedSidebarIconImage];
47		[parent addChildItem:_instaledFormulaeSidebarItem];
48		
49		_outdatedFormulaeSidebarItem = [PXSourceListItem itemWithTitle:NSLocalizedString(@"Sidebar_Item_Outdated", nil)
50															identifier:@"item"];
51		_outdatedFormulaeSidebarItem.icon = [self outdatedSidebarIconImage];
52		[parent addChildItem:_outdatedFormulaeSidebarItem];
53		
54		_allFormulaeSidebarItem = [PXSourceListItem itemWithTitle:NSLocalizedString(@"Sidebar_Item_All", nil)
55													   identifier:@"item"];
56		_allFormulaeSidebarItem.icon = [self allFormulaeSidebarIconImage];
57		[parent addChildItem:_allFormulaeSidebarItem];
58		
59		_leavesFormulaeSidebarItem = [PXSourceListItem itemWithTitle:NSLocalizedString(@"Sidebar_Item_Leaves", nil)
60														  identifier:@"item"];
61		_leavesFormulaeSidebarItem.icon = [self leavesSidebarIconImage];
62		[parent addChildItem:_leavesFormulaeSidebarItem];
63		
64		_repositoriesFormulaeSidebarItem = [PXSourceListItem itemWithTitle:NSLocalizedString(@"Sidebar_Item_Repos", nil)
65																identifier:@"item"];
66		_repositoriesFormulaeSidebarItem.icon = [self repositoriesSidebarIconImage];
67		[parent addChildItem:_repositoriesFormulaeSidebarItem];
68		
69		parent = [PXSourceListItem itemWithTitle:NSLocalizedString(@"Sidebar_Group_Tools", nil)
70									  identifier:@"group"];
71		[_rootSidebarCategory addChildItem:parent];
72		
73		item = [PXSourceListItem itemWithTitle:NSLocalizedString(@"Sidebar_Item_Doctor", nil)
74									identifier:@"item"];
75		[item setBadgeValue:@(-1)];
76		[item setIcon:[self doctorSidebarIconImage]];
77		[parent addChildItem:item];
78		
79		item = [PXSourceListItem itemWithTitle:NSLocalizedString(@"Sidebar_Item_Update", nil)
80									identifier:@"item"];
81		[item setBadgeValue:@(-1)];
82		[item setIcon:[self updateSidebarIconImage]];
83		[parent addChildItem:item];
84	}
85	
86	- (NSImage *)installedSidebarIconImage
87	{
88		if (@available(macOS 11.0, *)) {
89			return [NSImage imageWithSystemSymbolName:@"checkmark.square"
90							 accessibilityDescription:NSLocalizedString(@"Sidebar_Item_Installed", nil)];
91		} else {
92			return [NSImage imageNamed:@"installedTemplate"];
93		}
94	}
95	
96	- (NSImage *)outdatedSidebarIconImage
97	{
98		if (@available(macOS 11.0, *)) {
99			return [NSImage imageWithSystemSymbolName:@"clock.arrow.circlepath"
100							 accessibilityDescription:NSLocalizedString(@"Sidebar_Item_Outdated", nil)];
101		} else {
102			return [NSImage imageNamed:@"outdatedTemplate"];
103		}
104	}
105	
106	- (NSImage *)allFormulaeSidebarIconImage
107	{
108		if (@available(macOS 11.0, *)) {
109			return [NSImage imageWithSystemSymbolName:@"books.vertical"
110							 accessibilityDescription:NSLocalizedString(@"Sidebar_Item_All", nil)];
111		} else {
112			return [NSImage imageNamed:@"allFormulaeTemplate"];
113		}
114	}
115	
116	- (NSImage *)leavesSidebarIconImage
117	{
118		if (@available(macOS 11.0, *)) {
119			return [NSImage imageWithSystemSymbolName:@"leaf"
120							 accessibilityDescription:NSLocalizedString(@"Sidebar_Item_Leaves", nil)];
121		} else {
122			return [NSImage imageNamed:@"pinTemplate"];
123		}
124	}
125	
126	- (NSImage *)repositoriesSidebarIconImage
127	{
128		if (@available(macOS 11.0, *)) {
129			return [NSImage imageWithSystemSymbolName:@"building.columns"
130							 accessibilityDescription:NSLocalizedString(@"Sidebar_Item_Repos", nil)];
131		} else {
132			return [NSImage imageNamed:@"cloudTemplate"];
133		}
134	}
135	
136	- (NSImage *)doctorSidebarIconImage
137	{
138		if (@available(macOS 11.0, *)) {
139			return [NSImage imageWithSystemSymbolName:@"stethoscope"
140							 accessibilityDescription:NSLocalizedString(@"Sidebar_Item_Doctor", nil)];
141		} else {
142			return [NSImage imageNamed:@"doctorTemplate"];
143		}
144	}
145	
146	- (NSImage *)updateSidebarIconImage
147	{
148		if (@available(macOS 11.0, *)) {
149			return [NSImage imageWithSystemSymbolName:@"arrow.triangle.2.circlepath.circle"
150							 accessibilityDescription:NSLocalizedString(@"Sidebar_Item_Update", nil)];
151		} else {
152			return [NSImage imageNamed:@"updateTemplate"];
153		}
154	}
155	
156	
157	- (void)configureSidebarSettings
158	{
159		[self.sidebar selectRowIndexes:[NSIndexSet indexSetWithIndex:FormulaeSideBarItemInstalled] byExtendingSelection:NO];
160		[self.sidebar setAccessibilityLabel:NSLocalizedString(@"Sidebar_VoiceOver_Tools", nil)];
161	}
162	
163	- (void)refreshSidebarBadges
164	{
165		self.instaledFormulaeSidebarItem.badgeValue		= @([[[BPHomebrewManager sharedManager] installedFormulae] count]);
166		self.outdatedFormulaeSidebarItem.badgeValue		= @([[[BPHomebrewManager sharedManager] outdatedFormulae] count]);
167		self.allFormulaeSidebarItem.badgeValue			= @([[[BPHomebrewManager sharedManager] allFormulae] count]);
168		self.leavesFormulaeSidebarItem.badgeValue		= @([[[BPHomebrewManager sharedManager] leavesFormulae] count]);
169		self.repositoriesFormulaeSidebarItem.badgeValue = @([[[BPHomebrewManager sharedManager] repositoriesFormulae] count]);
170	}
171	
172	#pragma mark - PXSourceList Data Source
173	
174	- (NSUInteger)sourceList:(PXSourceList*)sourceList numberOfChildrenOfItem:(id)item
175	{
176		if (!item) { //Is root
177			return [[self.rootSidebarCategory children] count];
178		} else {
179			return [[(PXSourceListItem*)item children] count];
180		}
181	}
182	
183	- (id)sourceList:(PXSourceList*)sourceList child:(NSUInteger)index ofItem:(id)item
184	{
185		if (!item) {
186			return [[self.rootSidebarCategory children] objectAtIndex:index];
187		} else {
188			return [[(PXSourceListItem*)item children] objectAtIndex:index];
189		}
190	}
191	
192	- (BOOL)sourceList:(PXSourceList*)sourceList isItemExpandable:(id)item
193	{
194		if (!item) {
195			return YES;
196		} else {
197			return [item hasChildren];
198		}
199	}
200	
201	#pragma mark - PXSourceList Delegate
202	
203	- (BOOL)sourceList:(PXSourceList *)aSourceList isGroupAlwaysExpanded:(id)group
204	{
205		return YES;
206	}
207	
208	- (NSView *)sourceList:(PXSourceList *)aSourceList viewForItem:(id)item
209	{
210		PXSourceListTableCellView *cellView = nil;
211	
212		if ([[(PXSourceListItem*)item identifier] isEqualToString:@"group"]) {
213			cellView = [aSourceList makeViewWithIdentifier:@"HeaderCell" owner:nil];
214		} else {
215			cellView = [aSourceList makeViewWithIdentifier:@"MainCell" owner:nil];
216		}
217	
218		PXSourceListItem *sourceListItem = item;
219		cellView.textField.stringValue = sourceListItem.title;
220	
221		if (sourceListItem.badgeValue.integerValue >= 0)
222		{
223			cellView.badgeView.badgeValue = (NSUInteger) sourceListItem.badgeValue.integerValue;
224			[cellView.badgeView setHidden:NO];
225		}
226		else
227		{
228			[cellView.badgeView setHidden:YES];
229		}
230	
231		if (sourceListItem.icon) {
232			[cellView.imageView setImage:sourceListItem.icon];
233		}
234	
235		return cellView;
236	}
237	
238	- (void)sourceListSelectionDidChange:(NSNotification *)notification
239	{
240		if ([self.delegate respondsToSelector:@selector(sourceListSelectionDidChange)]) {
241			[self.delegate sourceListSelectionDidChange];
242		}
243	}
244	
245	#pragma mark - Actions
246	
247	- (IBAction)selectSideBarRowWithSenderTag:(id)sender
248	{
249		[self.sidebar selectRowIndexes:[NSIndexSet indexSetWithIndex:[sender tag]] byExtendingSelection:NO];
250	}
251	
252	@end
253

