				NSError *fallbackError = nil;
				cacheDict = [NSKeyedUnarchiver unarchivedObjectOfClass:[NSDictionary class] fromData:data error:&fallbackError];
				if (fallbackError) {
					NSLog(@"Failed decoding data: %@", [fallbackError localizedDescription]);
				}
