341	- (void)reconfigureItem:(NSToolbarItem *)item image:(NSImage *)image label:(NSString *)label action:(SEL)action
342	{
343		assert([NSThread isMainThread]);
344	
345		static BOOL (^staticBlock)(NSRect) = ^BOOL(NSRect dstRect) {
346			return YES;
347		};
348		
349		if (!image) {
350			if (@available(macOS 11.0, *)) {
351				item.view = nil;
352			} else {
353				item.image = [NSImage imageWithSize:NSMakeSize(32, 32) flipped:NO drawingHandler:staticBlock];
354			}
355	
356			item.action = action;
357		} else {
358			if (@available(macOS 11.0, *)) {
359				item.view = [self makeButtonForItemImage:image target:[self controller] action:action];
360			} else {
361				item.image = image;
362				item.action = action;
363			}
364		}
365	
366		item.label = label;
367		item.toolTip = label;
368	}
