388	- (void)makeSearchFieldFirstResponder
389	{
390		NSView *searchView;
391	
392		if (@available(macOS 11.0, *)) {
393			searchView = [(NSSearchToolbarItem *)[self toolbarItemSearch] searchField];
394		} else {
395			searchView = [[self toolbarItemSearch] view];
396		}
397	
398		[[searchView window] makeFirstResponder:searchView];
399	}
