401	#pragma mark - NSTextField Delegate
402	- (void)controlTextDidChange:(NSNotification *)aNotification
403	{
404		NSSearchField *field = (NSSearchField *)[aNotification object];
405		[self.controller performSearchWithString:field.stringValue];
406	}
