//
//  BPFormulaeDataSourceTests.m
//  CakebrewTests
//
//  Tests for BPFormulaeDataSource: it mirrors the BPHomebrewManager list for its
//  mode and provides bounds-safe row accessors.
//

#import <XCTest/XCTest.h>
#import "BPFormulaeDataSource.h"
#import "BPHomebrewManager.h"
#import "BPFormula.h"

@interface BPFormulaeDataSourceTests : XCTestCase
@property (strong) BPHomebrewManager *manager;
@end

@implementation BPFormulaeDataSourceTests

- (void)setUp
{
	[super setUp];
	self.manager = [BPHomebrewManager sharedManager];
	self.manager.installedFormulae = @[];
	self.manager.allFormulae = @[];
}

- (void)tearDown
{
	self.manager.installedFormulae = @[];
	self.manager.allFormulae = @[];
	self.manager = nil;
	[super tearDown];
}

- (void)testInstalledModeReflectsInstalledList
{
	BPFormula *git = [BPFormula formulaWithName:@"git"];
	BPFormula *wget = [BPFormula formulaWithName:@"wget"];
	self.manager.installedFormulae = @[ git, wget ];

	BPFormulaeDataSource *dataSource = [[BPFormulaeDataSource alloc] initWithMode:kBPListInstalled];

	XCTAssertEqual([dataSource numberOfRowsInTableView:nil], 2);
	XCTAssertEqualObjects([dataSource formulaAtIndex:0], git);
	XCTAssertEqualObjects([dataSource formulaAtIndex:1], wget);
}

- (void)testFormulaAtIndexOutOfBoundsReturnsNil
{
	self.manager.installedFormulae = @[ [BPFormula formulaWithName:@"git"] ];
	BPFormulaeDataSource *dataSource = [[BPFormulaeDataSource alloc] initWithMode:kBPListInstalled];

	XCTAssertNil([dataSource formulaAtIndex:5]);
	XCTAssertNil([dataSource formulaAtIndex:-1]);
}

- (void)testFormulasAtIndexSetReturnsSelectedFormulae
{
	BPFormula *a = [BPFormula formulaWithName:@"a"];
	BPFormula *b = [BPFormula formulaWithName:@"b"];
	BPFormula *c = [BPFormula formulaWithName:@"c"];
	self.manager.allFormulae = @[ a, b, c ];

	BPFormulaeDataSource *dataSource = [[BPFormulaeDataSource alloc] initWithMode:kBPListAll];

	NSMutableIndexSet *indexes = [NSMutableIndexSet indexSet];
	[indexes addIndex:0];
	[indexes addIndex:2];

	XCTAssertEqualObjects([dataSource formulasAtIndexSet:indexes], (@[ a, c ]));
}

- (void)testFormulasAtIndexSetOutOfRangeReturnsNil
{
	self.manager.installedFormulae = @[ [BPFormula formulaWithName:@"git"] ];
	BPFormulaeDataSource *dataSource = [[BPFormulaeDataSource alloc] initWithMode:kBPListInstalled];

	XCTAssertNil([dataSource formulasAtIndexSet:[NSIndexSet indexSetWithIndex:5]]);
}

- (void)testChangingModeRefreshesBackingArray
{
	self.manager.installedFormulae = @[ [BPFormula formulaWithName:@"git"] ];
	self.manager.allFormulae = @[ [BPFormula formulaWithName:@"a"], [BPFormula formulaWithName:@"b"] ];

	BPFormulaeDataSource *dataSource = [[BPFormulaeDataSource alloc] initWithMode:kBPListInstalled];
	XCTAssertEqual([dataSource numberOfRowsInTableView:nil], 1);

	dataSource.mode = kBPListAll;
	XCTAssertEqual([dataSource numberOfRowsInTableView:nil], 2);
}

@end

//
//  BPFormulaOptionTests.m
//  CakebrewTests
//
//  Tests for BPFormulaOption's NSCopying and NSSecureCoding conformance.
//

#import <XCTest/XCTest.h>
#import "BPFormulaOption.h"

@interface BPFormulaOptionTests : XCTestCase
@end

@implementation BPFormulaOptionTests

- (void)testSupportsSecureCoding
{
	XCTAssertTrue([BPFormulaOption supportsSecureCoding]);
}

- (void)testCopyPreservesNameAndExplanation
{
	BPFormulaOption *option = [[BPFormulaOption alloc] init];
	option.name = @"--with-foo";
	option.explanation = @"Build with foo support";

	BPFormulaOption *copy = [option copy];

	XCTAssertNotNil(copy);
	XCTAssertNotEqual(copy, option, @"copy should be a distinct instance");
	XCTAssertEqualObjects(copy.name, @"--with-foo");
	XCTAssertEqualObjects(copy.explanation, @"Build with foo support");
}

- (void)testSecureCodingRoundTrip
{
	BPFormulaOption *option = [[BPFormulaOption alloc] init];
	option.name = @"--HEAD";
	option.explanation = @"Install HEAD version";

	NSError *error = nil;
	NSData *data = [NSKeyedArchiver archivedDataWithRootObject:option requiringSecureCoding:YES error:&error];
	XCTAssertNil(error);
	XCTAssertNotNil(data);

	BPFormulaOption *decoded = [NSKeyedUnarchiver unarchivedObjectOfClass:[BPFormulaOption class] fromData:data error:&error];
	XCTAssertNil(error);
	XCTAssertEqualObjects(decoded.name, @"--HEAD");
	XCTAssertEqualObjects(decoded.explanation, @"Install HEAD version");
}

- (void)testSecureCodingPreservesNilFields
{
	// A bare option (no name/explanation) must round-trip without error.
	BPFormulaOption *option = [[BPFormulaOption alloc] init];

	NSError *error = nil;
	NSData *data = [NSKeyedArchiver archivedDataWithRootObject:option requiringSecureCoding:YES error:&error];
	XCTAssertNil(error);

	BPFormulaOption *decoded = [NSKeyedUnarchiver unarchivedObjectOfClass:[BPFormulaOption class] fromData:data error:&error];
	XCTAssertNil(error);
	XCTAssertNil(decoded.name);
	XCTAssertNil(decoded.explanation);
}

@end

//
//  BPMockHomebrewInterface.m
//  Cakebrew
//

#import "BPMockHomebrewInterface.h"
#import "BPFormula.h"

@implementation BPMockHomebrewInterface

// Always report Homebrew as present so the app never shows the disabled overlay.
- (BOOL)checkForHomebrew
{
	return YES;
}

// Serve deterministic fixture lists instead of running brew. installed / outdated
// / leaves / repositories are fetched fresh (not cached), so these drive the UI
// reproducibly.
- (NSArray<BPFormula *> *)listMode:(BPListMode)mode
{
	switch (mode) {
		case kBPListInstalled:
			return @[ [BPFormula formulaWithName:@"mockwget" andVersion:@"1.0.0"],
					  [BPFormula formulaWithName:@"mockgit" andVersion:@"2.39.0"],
					  [BPFormula formulaWithName:@"mockcurl" andVersion:@"8.0.0"] ];

		case kBPListOutdated:
			return @[ [BPFormula formulaWithName:@"mockgit" version:@"2.39.0" andLatestVersion:@"2.40.0"] ];

		case kBPListLeaves:
			return @[ [BPFormula formulaWithName:@"mockwget" andVersion:@"1.0.0"] ];

		case kBPListAll:
			return @[ [BPFormula formulaWithName:@"mockwget"],
					  [BPFormula formulaWithName:@"mockgit"],
					  [BPFormula formulaWithName:@"mockcurl"],
					  [BPFormula formulaWithName:@"mockhtop"] ];

		case kBPListRepositories:
			return @[ [BPFormula formulaWithName:@"homebrew/core"],
					  [BPFormula formulaWithName:@"homebrew/cask"] ];

		default:
			return @[];
	}
}

// Stream a fixed, recognizable doctor report instead of running `brew doctor`.
- (BOOL)runDoctorWithReturnBlock:(void (^)(NSString *))block
{
	if (block) {
		block(@"MOCK_DOCTOR_OK\nYour system is ready to brew.\n");
	}
	return YES;
}

// Stream a fixed, recognizable update report instead of running `brew update`.
- (BOOL)updateWithReturnBlock:(void (^)(NSString *))block
{
	if (block) {
		block(@"MOCK_UPDATE_OK\nAlready up-to-date.\n");
	}
	return YES;
}

// Stream a fixed, recognizable cleanup report instead of running `brew cleanup`.
- (BOOL)runCleanupWithReturnBlock:(void (^)(NSString *))block
{
	if (block) {
		block(@"MOCK_CLEANUP_OK\nFreed 0 bytes.\n");
	}
	return YES;
}

// Serve well-formed `brew info` output so selecting a formula doesn't shell out
// to real brew for a fixture name (which returns unparseable output and crashes
// BPFormula getInformation). The format matches what getInformation expects.
- (NSString *)informationForFormulaName:(NSString *)name
{
	return [NSString stringWithFormat:
			@"%@: stable 1.0.0\n"
			@"A mock formula used for Cakebrew UI tests.\n"
			@"https://example.com\n"
			@"Not installed\n", name];
}

- (NSString *)dependantsForFormulaName:(NSString *)name onlyInstalled:(BOOL)onlyInstalled
{
	return @"";
}

@end

