- (BPFormulaStatus)statusForFormula:(BPFormula*)formula
{
	if ([self searchForFormula:formula inArray:self.installedFormulae] >= 0)
	{
		if ([self searchForFormula:formula inArray:self.outdatedFormulae] >= 0)
		{
